+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * The filter a customer search applies: a free-text name and a set of statuses.
+ *
+ * <p>A customer matches when it satisfies both parts. The name is split on
+ * whitespace into terms, and every term must appear in the customer's first name
+ * or last name. Case and accents are ignored on both sides, so {@code makinen}
+ * matches {@code Mäkinen}, and {@code josephine} matches {@code Joséphine}.
+ *
+ * @param name     the text typed into the name filter; blank matches every name
+ * @param statuses the statuses to show; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter ALL = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    /** Returns a predicate that tests a customer against this filter. */
+    public Predicate<Customer> asPredicate() {
+        // The terms are folded once here, not once per customer.
+        List<String> terms = WHITESPACE.splitAsStream(fold(name))
+                .filter(term -> !term.isEmpty())
+                .toList();
+        return customer -> {
+            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+                return false;
+            }
+            String first = fold(customer.firstName());
+            String last = fold(customer.lastName());
+            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+        };
+    }
+
+    /** Strips accents and lower-cases, so that {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
